\n-- Exhistall Exhibition Booking Requests: read-only structural verification\n-- Run after 20260927_exhibition_booking_requests.sql.\n\nSELECT\n  to_regclass('public.exhibition_booking_requests') AS booking_requests_table,\n  to_regtype('public.exhibition_booking_status') AS booking_status_type,\n  (SELECT relrowsecurity FROM pg_class WHERE oid = 'public.exhibition_booking_requests'::regclass) AS booking_requests_rls_enabled;\n\nSELECT table_name, column_name, data_type, udt_name, is_nullable, column_default\nFROM information_schema.columns\nWHERE table_schema = 'public'\n  AND table_name = 'exhibition_booking_requests'\nORDER BY ordinal_position;\n\nSELECT conrelid::regclass AS table_name, conname AS constraint_name, pg_get_constraintdef(oid) AS definition\nFROM pg_constraint\nWHERE conrelid = 'public.exhibition_booking_requests'::regclass\nORDER BY conname;\n\nSELECT schemaname, tablename, policyname, cmd, qual, with_check\nFROM pg_policies\nWHERE schemaname = 'public'\n  AND tablename = 'exhibition_booking_requests'\nORDER BY policyname;\n\nSELECT indexname, indexdef\nFROM pg_indexes\nWHERE schemaname = 'public'\n  AND tablename = 'exhibition_booking_requests'\nORDER BY indexname;\n\nSELECT tgrelid::regclass AS table_name, tgname AS trigger_name, pg_get_triggerdef(oid) AS definition\nFROM pg_trigger\nWHERE tgrelid = 'public.exhibition_booking_requests'::regclass\n  AND NOT tgisinternal;\n